import { createPerson, getPersons } from "../components/apiutils";
import Nav from "../components/Nav";
import {useState,useEffect} from "react";


export default function UserMgmt(){
    const [users, setUsers] = useState([]);
    const [formData, setFormData] = useState({ name: "", email: "", mobile: "" });

    useEffect(()=>{
        getPersons()
        .then((users)=>{
            setUsers(users)
        })
    },[]);

    const handleChange = (event) => {
        const { name, value } = event.target;
        setFormData((prev) => ({ ...prev, [name]: value }));
    };

    const handleSubmit = (event) => {
        event.preventDefault();

        const newUser = {
            name: formData.name,
            email: formData.email,
            mobile: formData.mobile
        };

        setUsers((prevUsers) => [...prevUsers, newUser]);

        createPerson(formData)
            .catch(() => {
                console.log("Backend save failed, but the row is shown locally.");
            });

        setFormData({ name: "", email: "", mobile: "" });
    };

    return <>
    <Nav>
        <div style={{ padding: "20px" }}>
            <form onSubmit={handleSubmit} style={{ marginBottom: "20px" }}>
                <div>
                    <label>Name: </label>
                    <input name="name" value={formData.name} onChange={handleChange} required />
                </div>
                <div>
                    <label>Email: </label>
                    <input name="email" type="email" value={formData.email} onChange={handleChange} required />
                </div>
                <div>
                    <label>Phone: </label>
                    <input name="mobile" value={formData.mobile} onChange={handleChange} required />
                </div>
                <button type="submit">Add User</button>
            </form>

            <table>
                <thead>
                    <tr>
                        <th>Name</th>
                        <th>Email</th>
                        <th>Phone</th>
                        <th>Actions</th>
                    </tr>
                </thead>
                <tbody>
                    {users.map((user, index)=>{
                        return <tr key={`${user.email || index}-${index}`}>
                            <td>{user.name}</td>
                            <td>{user.email}</td>
                            <td>{user.mobile}</td> 
                        </tr>
                    })}
                </tbody>
            </table>
        </div>
    </Nav>
    </>
}
